.product-icon{width:30px;height:30px;display:grid;place-items:center;border-radius:9px;background:#DBEAFE;color:#2563EB;font-size:9px;font-weight:700}.product-icon{color:#059669;background:#D1FAE5}.empty{min-height:150px;display:grid;place-items:center;padding:20px;color:#94A3B8;font-size:11px;text-align:center}.dashboard-rail{min-width:0;display:flex;flex-direction:column;gap:14px}.quick{width:100%;height:52px;margin-bottom:8px;border:1px solid #E2E8F0;border-radius:12px;background:#fff;display:flex;align-items:center;gap:10px;padding:0 11px;color:#0F172A;font-size:11px;font-weight:600;box-shadow:0 3px 12px rgba(15,23,42,.035);cursor:pointer}.quick>span:first-child{width:31px;height:31px;border-radius:9px;display:grid;place-items:center;color:#fff;background:#2563EB}.quick.green>span:first-child{background:#10B981}.quick.teal>span:first-child{background:#06B6D4}.quick.purple>span:first-child{background:#7C3AED}.quick.navy>span:first-child{background:#0F172A}.quick>b{margin-left:auto;color:#2563EB;font-size:19px}.tip{padding:20px 15px;border:1px solid #DBEAFE;border-radius:14px;background:linear-gradient(180deg,#EFF6FF 0%,#F8FBFF 100%);text-align:center}.tip>div{width:52px;height:52px;margin:0 auto 11px;border-radius:50%;display:grid;place-items:center;background:#D1FAE5;color:#059669}.tip h3{margin:0;color:#0F172A;font-size:16px}.tip p{margin:8px 0 14px;color:#64748B;font-size:10px;line-height:1.55}.tip button{width:100%;height:34px;border:0;border-radius:9px;background:#2563EB;color:#fff;font-size:11px;font-weight:700;cursor:pointer}.connected{margin-top:auto;display:flex;align-items:center;justify-content:center;gap:7px;padding:11px 8px;border-top:1px solid #E2E8F0;color:#64748B;font-size:9px}.connected i{width:7px;height:7px;border-radius:50%;background:#10B981;box-shadow:0 0 0 3px #D1FAE5}@media(max-width:1260px){.dashboard-shell{grid-template-columns:minmax(0,1fr) 210px;padding:18px}.primary-grid{grid-template-columns:1fr}.secondary-grid{grid-template-columns: